describe('Table Summary Row', () => {
    beforeEach(() => {
        cy.visit('/table-page'); // Replace with the actual URL of the page containing the table
    });

    it('should display the summary row at the bottom of the numeric column', () => {
        cy.get('table').within(() => {
            cy.get('tbody tr').should('have.length.greaterThan', 0); // Ensure there are rows in the table
            cy.get('tr:last-child').within(() => {
                cy.get('td.numeric-column').should('exist'); // Replace with the actual selector for the numeric column
                cy.get('td.numeric-column').should('contain.text', 'Total'); // Check if the summary row contains 'Total'
                cy.get('td.numeric-column').invoke('text').then((text) => {
                    const total = parseFloat(text.replace(/[^0-9.-]+/g, ""));
                    expect(total).to.be.gte(0); // Ensure the total is a non-negative number
                });
            });
        });
    });

    it('should not display the summary row if there are no numeric entries', () => {
        // Simulate a scenario where there are no numeric entries
        cy.intercept('GET', '/api/table-data', { fixture: 'emptyTableData.json' }).as('getEmptyTableData'); // Replace with actual API call
        cy.wait('@getEmptyTableData');

        cy.get('table').within(() => {
            cy.get('tbody tr').should('have.length', 0); // Ensure there are no rows in the table
            cy.get('tr:last-child').should('not.exist'); // Summary row should not exist
        });
    });
});
